"""Build self-contained local style pages and collection index; no image generation."""
from pathlib import Path
import json,html,re,hashlib
r=Path(__file__).resolve().parent
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
styles=read(r/'styles.json')+read(r/'styles_next20.json')+read(r/'styles_collection03.json')
base=[('01_moodboard.png','Material moodboard'),('02_palette.png','Color palette'),('03_example_living.png','Living room'),('04_example_bedroom.png','Bedroom'),('05_example_dining.png','Dining room')]
views=[('21_Living_Wide.png','Living · wide'),('20_Living_Alternate.png','Living · alternate'),('23_Dining_Wide.png','Dining · reverse'),('31_Bedroom_Primary_Wide.png','Primary bedroom'),('10_Solarium.png','Solarium')]
e=html.escape
def selected(d,name):
 vs=sorted(d.glob(Path(name).stem+'_v*.png'),key=lambda p:int(p.stem.rsplit('_v',1)[1]))
 p=vs[-1] if vs else d/name
 return p.name if p.exists() else None
css="""
:root{--ink:#292d28;--paper:#f4f0e7;--line:#d7d4c9;--accent:#435a48}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,sans-serif}a{color:inherit;text-underline-offset:4px}button,input{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #aa6647;outline-offset:4px}header{border-bottom:1px solid var(--line)}.top{display:flex;justify-content:space-between;gap:20px;padding:20px 4vw;align-items:center}.brand{font:23px Georgia;text-decoration:none}.micro{font-size:11px;letter-spacing:.19em;text-transform:uppercase}.wrap{max-width:1440px;margin:auto;padding:0 4vw}.hero{display:grid;grid-template-columns:1fr 1.2fr;gap:5vw;align-items:center;padding:58px 0}.hero h1{font:clamp(40px,5.2vw,80px)/1.03 Georgia;margin:20px 0}.lead{font-size:19px;max-width:620px;color:#555c52}.hero img{width:100%;aspect-ratio:1.36;object-fit:cover;border-radius:120px 2px 2px 2px}.pill{display:inline-block;border:1px solid var(--line);padding:5px 13px;border-radius:30px;font-size:12px}.nav{position:sticky;top:0;z-index:5;background:#f4f0e7f5;backdrop-filter:blur(10px);display:flex;gap:22px;overflow:auto;padding:16px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.nav a{white-space:nowrap;text-decoration:none;font-size:13px}section{padding:56px 0;border-bottom:1px solid var(--line);scroll-margin-top:65px}h2{font:clamp(28px,3vw,44px)/1.12 Georgia;margin:0 0 20px}h3{font:24px Georgia;margin:12px 0}p{margin:0 0 18px}.sectionhead{display:flex;justify-content:space-between;gap:20px;align-items:end}.muted{color:#646b61;font-size:14px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:40px}.materials{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0}.materials span{border:1px solid var(--line);border-radius:30px;padding:8px 16px}.swatches{display:flex;margin:26px 0;gap:10px}.swatch{flex:1}.swatch i{display:block;height:110px;border-radius:50px 50px 2px 2px;border:1px solid #0001}.swatch code{display:block;margin-top:10px;font-size:12px}.media{margin:0}.media button{padding:0;border:0;background:none;width:100%;display:block}.media img{width:100%;display:block;object-fit:contain;background:#ede8df}.media figcaption{padding:12px 0;font-size:13px;color:#596153}.triple{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.triple img{aspect-ratio:1.45;object-fit:cover}.empty{display:grid;place-items:center;text-align:center;min-height:230px;background:#e8e4d9;border:1px dashed #c6c3b7;padding:30px;color:#697163}.tabs{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0}.tabs button,.toggle,.zoom,.favorite{border:1px solid #bfc5b8;border-radius:30px;padding:9px 18px;background:transparent;color:var(--ink)}.tabs button[aria-pressed=true],.favorite[aria-pressed=true]{background:var(--accent);color:white}.viewer{background:#e8e4dc;position:relative;min-height:200px}.viewer img{display:block;width:100%;aspect-ratio:16/11;object-fit:contain}.viewer .empty{aspect-ratio:16/11}.viewerbar{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:14px 0}.schedule{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}.schedule article{border-top:2px solid #9ea58e;padding-top:16px}.steps{padding-left:24px}.steps li{padding:0 0 15px 10px}.note{padding:20px 24px;background:#e7e7dc;border-left:3px solid #929e81}.records{font-size:13px;display:flex;gap:18px;flex-wrap:wrap;margin-top:30px}footer{padding:38px 4vw;display:flex;justify-content:space-between;gap:20px}dialog{border:0;background:#181b18;color:white;width:96vw;max-width:none;height:94vh;padding:20px}dialog::backdrop{background:#000b}dialog img{background:#ede8df;display:block;max-width:100%;max-height:calc(94vh - 85px);margin:auto;object-fit:contain}dialog button{float:right;background:none;color:white;border:1px solid #888;padding:6px 15px;margin-bottom:10px}.catalogtitle{font:clamp(48px,7vw,100px)/1.03 Georgia;max-width:900px;margin:35px 0}.catalogintro{padding:55px 0 35px}.searchbar{display:flex;gap:12px;flex-wrap:wrap;margin:25px 0}.searchbar input{flex:1;min-width:220px;padding:14px 20px;border:1px solid #bdc4b5;border-radius:30px;background:#fcfaf5}.searchbar button{border:1px solid #bdc4b5;border-radius:30px;background:none;padding:10px 20px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:36px 24px;padding:20px 0 60px}.card{text-decoration:none;display:block}.card img{width:100%;aspect-ratio:1.4;object-fit:cover;border-radius:50px 2px 2px 2px;transition:filter .2s}.card:hover img{filter:brightness(1.06)}.card h2{font:27px Georgia;margin:10px 0}.card p{font-size:14px}.mini{display:flex;gap:4px;margin:12px 0}.mini i{width:24px;height:10px;border-radius:4px}[hidden]{display:none!important}@media(max-width:800px){.hero,.cols{grid-template-columns:1fr}.hero{padding:35px 0;gap:20px}.hero img{max-height:500px}.triple,.schedule{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}.sectionhead{display:block}.swatches{gap:5px}.swatch i{height:80px}.nav{gap:16px}.top .micro{display:none}}@media(max-width:480px){.cards{grid-template-columns:1fr}.swatch code{font-size:10px}.viewerbar{align-items:start;flex-direction:column}footer{flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
"""
css += '\n.style-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}.not-for-me{border:1px solid #bfc5b8;border-radius:30px;padding:9px 18px;background:transparent;color:var(--ink)}.not-for-me[aria-pressed=true]{background:#e8ded5;border-color:#a68c79}.card-link{display:block;text-decoration:none}.card .style-actions button{font-size:13px;padding:8px 14px}.preference-feedback{min-height:1.65em;margin:16px 0 0;font-size:14px;color:#596153}.excluded-section{border-top:1px solid var(--line)}.excluded-section .cards{padding-bottom:0}\n'
css += '\n.style-actions .favorite,.style-actions .not-for-me{-webkit-appearance:none;appearance:none;display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;min-height:44px;font:inherit;line-height:1.4;padding:10px 18px;touch-action:manipulation}.card .style-actions .favorite,.card .style-actions .not-for-me{font-size:14px;padding:10px 16px}\n'
(r/'style-pages.css').write_text(css.strip()+'\n',encoding='utf-8')
js="""
const dialog=document.querySelector('dialog');
document.querySelectorAll('[data-enlarge]').forEach(b=>b.addEventListener('click',()=>{dialog.querySelector('img').src=b.dataset.enlarge;dialog.querySelector('img').alt=b.dataset.caption||'';dialog.showModal()}));
dialog?.querySelector('button').addEventListener('click',()=>dialog.close());
dialog?.addEventListener('click',ev=>{if(ev.target===dialog)dialog.close()});
let active=0,original=false;
const dataEl=document.querySelector('#view-data');
if(dataEl){const views=JSON.parse(dataEl.textContent),area=document.querySelector('.viewer'),label=document.querySelector('#view-label'),toggle=document.querySelector('.toggle'),zoom=document.querySelector('.zoom');
function paint(){const v=views[active],src=original?v.original:v.image;area.replaceChildren();if(src){const im=document.createElement('img');im.src=src;im.alt=(original?'Empty reference: ':'Style concept: ')+v.label;area.append(im)}else{const d=document.createElement('div');d.className='empty';d.textContent='This condo view is awaiting generation.';area.append(d)}label.textContent=(original?'Empty condo reference · ':'Furnished concept · ')+v.label;toggle.textContent=original?'Show styled view':'Show empty reference';toggle.setAttribute('aria-pressed',String(original));zoom.disabled=!src;document.querySelectorAll('[data-view]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===active)))}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{active=Number(b.dataset.view);paint()}));toggle.addEventListener('click',()=>{original=!original;paint()});zoom.addEventListener('click',()=>{const v=views[active];dialog.querySelector('img').src=original?v.original:v.image;dialog.querySelector('img').alt=v.label;dialog.showModal()});paint()}
const preferenceKeys={favorites:'condo-style-favorites',excluded:'condo-style-not-for-me'};
function readPreference(key){try{const values=JSON.parse(localStorage.getItem(key)||'[]');return new Set(Array.isArray(values)?values.filter(v=>typeof v==='string'):[])}catch{return new Set()}}
let saved=readPreference(preferenceKeys.favorites),excluded=readPreference(preferenceKeys.excluded);
function persistPreferences(){try{localStorage.setItem(preferenceKeys.favorites,JSON.stringify([...saved]));localStorage.setItem(preferenceKeys.excluded,JSON.stringify([...excluded]))}catch{}}
const search=document.querySelector('#search'),cards=[...document.querySelectorAll('.card')];
let only=false,collection=new URLSearchParams(location.search).get('collection')||'all';
if(!['all','favorites','jazz'].includes(collection))collection='all';
function paintPreferences(){
 document.querySelectorAll('.favorite').forEach(b=>{const on=saved.has(b.dataset.id)&&!excluded.has(b.dataset.id);b.setAttribute('aria-pressed',String(on));b.textContent=on?'Saved to shortlist':'Save to shortlist'});
 document.querySelectorAll('.not-for-me').forEach(b=>{const on=excluded.has(b.dataset.id);b.setAttribute('aria-pressed',String(on));b.textContent=on?'Restore to main list':'Not for me'});
 if(!search)return;
 const main=document.querySelector('#main-styles'),dismissed=document.querySelector('#excluded-styles'),q=search.value.toLowerCase().trim();
 let count=0,excludedCount=0;
 cards.forEach(c=>{
  const rejected=excluded.has(c.dataset.id),target=rejected?dismissed:main;
  if(c.parentElement!==target)target.append(c);
  const match=c.dataset.search.includes(q)&&(collection==='all'||c.dataset.collection===collection);
  const show=match&&(rejected||!only||saved.has(c.dataset.id));c.hidden=!show;
  if(show){if(rejected)excludedCount++;else count++}
 });
 // Restore the original collection order after moving cards between sections.
 [main,dismissed].forEach(container=>[...container.children].sort((a,b)=>Number(a.dataset.id)-Number(b.dataset.id)).forEach(c=>container.append(c)));
 document.querySelector('#result-count').textContent=count+(count===1?' style':' styles')+' shown in the main list';
 document.querySelector('#excluded-count').textContent=excludedCount+(excludedCount===1?' style':' styles')+' shown · '+excluded.size+' set aside';
 const empty=document.querySelector('#excluded-empty');empty.hidden=excludedCount>0;
 empty.textContent=excluded.size?'No excluded styles match this search or collection.':'Styles you mark “Not for me” will appear here. You can restore them whenever you like.';
}
document.querySelectorAll('.favorite,.not-for-me').forEach(b=>b.addEventListener('click',()=>{
 const id=b.dataset.id;
 if(b.classList.contains('favorite')){if(saved.has(id)&&!excluded.has(id))saved.delete(id);else{saved.add(id);excluded.delete(id)}}
 else if(excluded.has(id))excluded.delete(id);else{excluded.add(id);saved.delete(id)}
 persistPreferences();paintPreferences();
 const message=document.querySelector('#preference-feedback');if(message)message.textContent=b.classList.contains('favorite')?(saved.has(id)?'Style saved to your shortlist.':'Style removed from your shortlist.'):(excluded.has(id)?'Style moved to Not for me.':'Style restored to the main list.');
}));
if(search){
 document.querySelectorAll('[data-filter]').forEach(b=>{b.addEventListener('click',()=>{collection=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));paintPreferences()});b.setAttribute('aria-pressed',String(b.dataset.filter===collection))});
 search.addEventListener('input',paintPreferences);
 document.querySelector('#shortlist').addEventListener('click',ev=>{only=!only;ev.currentTarget.textContent=only?'Show all styles':'Show my shortlist';ev.currentTarget.setAttribute('aria-pressed',String(only));paintPreferences()});
}
function refreshPreferences(){saved=readPreference(preferenceKeys.favorites);excluded=readPreference(preferenceKeys.excluded);paintPreferences()}
window.addEventListener('storage',refreshPreferences);window.addEventListener('pageshow',refreshPreferences);
paintPreferences();
"""
(r/'style-pages.js').write_text(js.strip()+'\n',encoding='utf-8')
asset_versions={kind:hashlib.sha256((r/f'style-pages.{kind}').read_bytes()).hexdigest()[:12] for kind in ('css','js')}
def media(d,name,title):
 f=selected(d,name)
 if not f:return f'<figure class="media"><div class="empty">{e(title)}<br>Awaiting generation</div><figcaption>{e(title)}</figcaption></figure>'
 return f'<figure class="media"><button data-enlarge="{e(f)}" data-caption="{e(title)}" aria-label="Enlarge {e(title)}"><img loading="lazy" src="{e(f)}" alt="{e(title)}"></button><figcaption>{e(title)} · click to enlarge</figcaption></figure>'
all_status=[];cards=[]
for i,s in enumerate(styles):
 d=r/s['folder']; name=s['name']; assets={f:selected(d,f) for f,_ in base};assets.update({'condo_'+f:selected(d,'condo_'+f) for f,_ in views});saved=sum(bool(v) for v in assets.values())
 review=read(d/'review.json') if (d/'review.json').exists() else {}
 pending=review.get('pending_corrections',[]);approved=review.get('approved',False)
 state='reviewed' if approved and saved==10 else 'corrections_pending' if pending else 'generated_pending_review' if saved==10 else 'in_progress'
 status={'style':name,'expected':10,'saved':saved,'state':state,'selected_outputs':assets,'review':review}
 (d/'status.json').write_text(json.dumps(status,indent=2))
 all_status.append(status)
 if int(s['id'])>20:
  spec=read(d/'prompt.json');spec['generation_records']=[read(p) for p in d.glob('*.generation.json')];spec['selected_outputs']={k:{'file':v,'sha256':hashlib.sha256((d/v).read_bytes()).hexdigest()} for k,v in assets.items() if v};(d/'prompt.json').write_text(json.dumps(spec,indent=2));(d/'prompts.json').write_text(json.dumps(spec,indent=2))
 hero=assets['condo_21_Living_Wide.png'] or assets['03_example_living.png'] or assets['01_moodboard.png']
 herohtml=f'<img src="{hero}" alt="{e(name)} interior concept">' if hero else '<div class="empty">Your next design direction<br>Images in progress</div>'
 blend=s.get('blend','Collection 01 · individual style')
 living=s['living'].replace('six ','four ')
 mats=''.join(f'<span>{e(x.strip())}</span>' for x in s['materials'].split(';'))
 swatches=''.join(f'<div class="swatch"><i style="background:{c}"></i><code>{c}</code></div>' for c in s['colors'])
 badge='Concept review passed' if state=='reviewed' else 'Corrections pending' if pending else f'{saved}/10 images saved · review pending'
 piano=('<div class="note"><h3>A piano lounge for everyday life</h3><p>Kawai NV12: 151.5 cm wide × 87 cm deep. Reserve additional bench and playing space, plus a separate circulation route. Pair a 180 cm sofa and comfortable chair with a 100 cm round dining table for four. The piano stays on the solid living-room wall, clear of the refrigerator; TV beside it, never above the opening lid.</p><p>Use dimmable table and floor lamps, one textured feature wall, a small stepped Art Deco mirror and two framed jazz portraits. Choose ready-made furniture and veneer, then spend selectively on comfortable upholstery and lighting. The full guide explains daytime living, evening lighting and furnishing priorities.</p><p>Concept placement requires a measured fit check before purchase. <a href="../ref/NV12-angled.jpg">Piano reference</a> · <a href="../ref/NV12_dimensions.jpeg">Dimensions</a> · <a href="https://www.kawai-global.com/product/nv12/">Kawai specifications</a></p></div>') if s.get('collection')=='jazz' else ''
 note=('<div class="note"><b>Review notes</b><p>'+e(' '.join(x['required_change'] for x in pending))+'</p></div>') if pending else ''
 vdata=[{'label':title,'image':assets['condo_'+f],'original':'../ref/'+f} for f,title in views]
 tabs=''.join(f'<button data-view="{k}" aria-pressed="{str(k==0).lower()}">{e(title)}</button>' for k,(_,title) in enumerate(views))
 prev=styles[(i-1)%len(styles)];nxt=styles[(i+1)%len(styles)]
 page=f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(name)} · Condo style studio</title><link rel="stylesheet" href="../style-pages.css?v={asset_versions['css']}"></head><body>
<header class="top"><a class="brand" href="../index.html">Condo / Style studio</a><span class="micro">Burnaby Lake · Direction {s['id']} of {len(styles)}</span><a href="../index.html">All styles ↗</a></header>
<main class="wrap"><div class="hero"><div><span class="micro">{e(blend)}</span><h1>{e(name)}</h1><p class="lead">{e(s['definition'])}</p><p><span class="pill">{badge}</span></p><div class="style-actions"><button class="favorite" data-id="{s['id']}" aria-pressed="false">Save to shortlist</button><button class="not-for-me" data-id="{s['id']}" aria-pressed="false">Not for me</button></div><p id="preference-feedback" class="preference-feedback" role="status" aria-live="polite"></p></div>{herohtml}</div>
<nav class="nav" aria-label="Style sections"><a href="#direction">The direction</a><a href="#palette">Palette & materials</a><a href="#examples">Room inspiration</a><a href="#condo">Your condo</a><a href="#implementation">Make it yours</a></nav>
<section id="direction"><div class="cols"><div><span class="micro">01 / Character</span><h2>A room with a point of view.</h2><p>{e(s['implement'])}</p><p class="muted">The furniture, lighting and material choices establish the style. The condo's existing cream kitchen, black marble, glazing and floors provide the common starting point.</p></div><div><h3>The material vocabulary</h3><div class="materials">{mats}</div><p><b>Keep it focused.</b> {e(s['avoid'])}</p></div></div></section>
<section id="palette"><span class="micro">02 / Atmosphere</span><h2>Color you can live with.</h2><div class="swatches">{swatches}</div><p class="muted">Exact digital swatches. Confirm physical fabric and finish samples in daylight and evening light.</p><div class="cols">{media(d,'01_moodboard.png','Material moodboard')}{media(d,'02_palette.png','Color palette artwork')}</div></section>
<section id="examples"><div class="sectionhead"><div><span class="micro">03 / Inspiration</span><h2>The style, room by room.</h2></div><p class="muted">Generic examples · other interiors</p></div><div class="triple">{''.join(media(d,f,title) for f,title in base[2:])}</div></section>
<section id="condo"><div class="sectionhead"><div><span class="micro">04 / In your home</span><h2>Same condo. A different feeling.</h2></div><p class="muted">Five camera views · compare with the empty shell</p></div>{note}<div class="tabs" aria-label="Choose condo camera">{tabs}</div><div class="viewer"></div><div class="viewerbar"><span id="view-label" class="muted" aria-live="polite"></span><div><button class="toggle" aria-pressed="false">Show empty reference</button> <button class="zoom">Enlarge</button></div></div><p class="muted">AI furnishing concepts. Small differences in scale, artwork or placement can occur between views; these are not measured construction renders.</p></section>
<section id="implementation"><span class="micro">05 / Make it yours</span><h2>From a feeling to a furnishing plan.</h2>{piano}<div class="schedule"><article><h3>Living & dining</h3><p>{e(living)}.</p><p class="muted">One sofa, one accent chair, coffee table, TV and media cabinet. A compact indoor dining table for four.</p></article><article><h3>Primary bedroom</h3><p>{e(s['bed'])}.</p><p class="muted">Queen bed, two compact nightstands and two lamps. Preserve access to doors and operable glazing.</p></article><article><h3>Solarium</h3><p>{e(s['solarium'])}.</p><p class="muted">Use outdoor frames and weatherproof textiles; keep the structural pillar and passages clear.</p></article></div><div class="cols"><div><h3>Build the room in layers</h3><ol class="steps"><li>Start with upholstery and timber samples beside the existing floor, cream cabinetry and black marble.</li><li>{e(s['implement'])}</li><li>Resolve the sofa, chair, media cabinet and dining set together. Repeat the selected designs across the shared room.</li><li>Carry the material family into the bedroom and outdoor furnishings, then finish with rugs, lamps and artwork.</li><li>Check actual dimensions and chair pull-out space in the calibrated Blender model before purchasing.</li></ol></div><div><h3>Room essentials</h3><p>Queen mattress: 152.4 × 203.2 cm. Ceiling: 2.7 m. Compact dining target: approximately 105 cm round or 120 × 75 cm rectangular, seating four.</p><div class="note">The five current empty references define this collection. They supersede the original guides' older seven-view and six-chair scope. The saved Blender model is unchanged.</div></div></div><div class="records"><a href="GUIDE.md">Read the full guide</a><a href="prompt.json">Prompts & provenance</a><a href="status.json">Generation & review status</a><a href="../REFERENCE_MAP.md">Camera map</a><a href="../COLLECTION_02.md">Collection research</a></div></section></main>
<footer><a href="../{prev['folder']}/index.html">← {e(prev['name'])}</a><span class="micro">Style {s['id']} / {len(styles)}</span><a href="../{nxt['folder']}/index.html">{e(nxt['name'])} →</a></footer><dialog aria-label="Enlarged image"><button aria-label="Close enlarged image">Close ×</button><img alt=""></dialog><script id="view-data" type="application/json">{json.dumps(vdata)}</script><script src="../style-pages.js?v={asset_versions['js']}"></script></body></html>"""
 (d/'index.html').write_text(page.strip()+'\n',encoding='utf-8')
 thumb=f'<img loading="lazy" src="{s["folder"]}/{hero}" alt="{e(name)}">' if hero else '<div class="empty">Images in progress</div>'
 mini=''.join(f'<i style="background:{c}"></i>' for c in s['colors'])
 cards.append(f'<article class="card" data-id="{s["id"]}" data-collection="{s.get('collection','original')}" data-search="{e((name+" "+blend+" "+s["materials"]).lower())}" ><a class="card-link" href="{s["folder"]}/index.html">{thumb}<div class="mini">{mini}</div><span class="micro">{s["id"]} / {e(blend)}</span><h2>{e(name)}</h2><p>{e(s["definition"])}</p><span class="pill">{badge}</span></a><div class="style-actions"><button class="favorite" data-id="{s["id"]}" aria-pressed="false">Save to shortlist</button><button class="not-for-me" data-id="{s["id"]}" aria-pressed="false">Not for me</button></div></article>')
total=sum(s['saved'] for s in all_status)
index=f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{len(styles)} ways to feel at home · Condo style studio</title><link rel="stylesheet" href="style-pages.css?v={asset_versions['css']}"></head><body><header class="top"><a class="brand" href="index.html">Condo / Style studio</a><span class="micro">Burnaby Lake · Interior explorations</span></header><main class="wrap"><div class="catalogintro"><span class="micro">The collection / 01—{len(styles)}</span><h1 class="catalogtitle">Find your way<br>to feel at home.</h1><p class="lead">{len(styles)} design directions for the same condo. Explore the materials, see the rooms, and save the styles you want to live with.</p><p class="muted">{total}/{len(styles)*10} images saved. Each style page includes its guide, palette, examples, condo views and review notes.</p><div class="tabs" aria-label="Choose collection"><button data-filter="all">All 53 styles</button><button data-filter="favorites">10 variations of your favorites</button><button data-filter="jazz">3 Jazz Piano Lounges</button></div><div class="searchbar"><input id="search" aria-label="Search styles" placeholder="Search a style, material or combination…"><button id="shortlist" aria-pressed="false">Show my shortlist</button></div><span id="result-count" class="micro" aria-live="polite"></span><p class="muted">Mark a style “Not for me” to move it to the section below. Save your favorites to build a shortlist.</p><p id="preference-feedback" class="preference-feedback" role="status" aria-live="polite"></p></div><div id="main-styles" class="cards">{''.join(cards)}</div><section id="not-for-me" class="excluded-section" aria-labelledby="excluded-heading"><span class="micro">Set aside for now</span><h2 id="excluded-heading">Not for me</h2><p class="muted">These styles are out of your main list. Restore a style or save it to your shortlist to bring it back.</p><p id="excluded-count" class="micro" aria-live="polite"></p><p id="excluded-empty" class="muted"></p><div id="excluded-styles" class="cards"></div></section><p class="muted">Current and enduring directions, not a statistical popularity ranking. <a href="README.md">Original research</a> · <a href="COLLECTION_02.md">Next collection</a> · <a href="REFERENCE_MAP.md">Reference map</a>. Your shortlist and “Not for me” choices are stored in this browser.</p></main><footer><span class="brand">Condo / Style studio</span><span class="micro">Designed around your home</span></footer><script src="style-pages.js?v={asset_versions['js']}"></script></body></html>"""
(r/'index.html').write_text(index,encoding='utf-8')
(r/'collection-status.json').write_text(json.dumps({'expected':len(styles)*10,'saved':total,'styles':all_status},indent=2))
print(f'{len(styles)} style pages + collection index; {total}/{len(styles)*10} assets saved')
